package com.medicinemanager.controller;
import com.medicinemanager.dto.*;import com.medicinemanager.mapper.EntityMapper;import com.medicinemanager.service.MedicationPeriodService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;import java.net.URI;
@RestController @RequestMapping("/api/medication-periods") public class MedicationPeriodController{private final MedicationPeriodService s;private final EntityMapper m;public MedicationPeriodController(MedicationPeriodService s,EntityMapper m){this.s=s;this.m=m;}@PostMapping ResponseEntity<Responses.MedicationPeriodResponse> create(@Valid @RequestBody Requests.MedicationPeriodRequest x){var created=s.create(x);return ResponseEntity.created(URI.create("/api/medication-periods/"+created.getId())).body(m.medicationPeriod(created));}@GetMapping List<Responses.MedicationPeriodResponse> all(){return s.findAll().stream().map(m::medicationPeriod).toList();}@GetMapping("/{id}") Responses.MedicationPeriodResponse one(@PathVariable UUID id){return m.medicationPeriod(s.find(id));}@PutMapping("/{id}") Responses.MedicationPeriodResponse update(@PathVariable UUID id,@Valid @RequestBody Requests.MedicationPeriodRequest x){return m.medicationPeriod(s.update(id,x));}@DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable UUID id){s.delete(id);return ResponseEntity.noContent().build();}}
